import json
import logging
import os
import subprocess
import sys
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, Optional

# Sensitive information must be loaded from environment variables
POOL_API_KEY = os.getenv("CRYPTO_POOL_API_KEY", "")
WALLET_ADDRESS = os.getenv("CRYPTO_WALLET_ADDRESS", "")

CONFIG_DIR = Path("/tmp/zalupa")
CONFIG_FILE = CONFIG_DIR / "config.json"
LOG_FILE = CONFIG_DIR / "mining.log"

class MiningConfig:
    def __init__(self, config_path: Path):
        self.config_path = config_path
        self.config: Dict[str, Any] = {}
        self._load_config()

    def _load_config(self) -> None:
        if not self.config_path.exists():
            self.config = {
                "pool": {
                    "url": "stratum+tcp://pool.example.com:3333",
                    "nicehash": False,
                    "enabled": True
                },
                "worker": {
                    "name": "default_worker",
                    "cpu_limit": 80
                }
            }
            self._save_config()
        else:
            try:
                with open(self.config_path, "r", encoding="utf-8") as f:
                    self.config = json.load(f)
            except json.JSONDecodeError as e:
                logging.error(f"Failed to parse config file: {e}")
                self.config = {
                    "pool": {"url": "", "nicehash": False, "enabled": False},
                    "worker": {"name": "default_worker", "cpu_limit": 80}
                }

    def _save_config(self) -> None:
        try:
            with open(self.config_path, "w", encoding="utf-8") as f:
                json.dump(self.config, f, indent=4)
        except IOError as e:
            logging.error(f"Failed to save config: {e}")

    def get_pool_url(self) -> str:
        return self.config.get("pool", {}).get("url", "")

    def is_nicehash(self) -> bool:
        return self.config.get("pool", {}).get("nicehash", False)

    def is_pool_enabled(self) -> bool:
        return self.config.get("pool", {}).get("enabled", False)

    def get_worker_name(self) -> str:
        return self.config.get("worker", {}).get("name", "default_worker")

    def get_cpu_limit(self) -> int:
        return self.config.get("worker", {}).get("cpu_limit", 80)

class ResourceMonitor:
    def __init__(self, log_path: Path):
        self.log_path = log_path
        self.start_time: Optional[datetime] = None
        self._setup_logging()

    def _setup_logging(self) -> None:
        self.logger = logging.getLogger("MiningMonitor")
        self.logger.setLevel(logging.INFO)
        self.logger.handlers.clear()

        file_handler = logging.FileHandler(self.log_path)
        file_handler.setLevel(logging.INFO)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def log_activity(self, message: str) -> None:
        try:
            self.logger.info(message)
        except Exception as e:
            print(f"Logging error: {e}", file=sys.stderr)

    def start(self) -> None:
        self.start_time = datetime.now()
        self.log_activity("Mining process started.")

    def stop(self) -> None:
        if self.start_time:
            duration = datetime.now() - self.start_time
            self.log_activity(f"Mining process stopped. Uptime: {duration}")

    def get_uptime_seconds(self) -> float:
        if self.start_time:
            return (datetime.now() - self.start_time).total_seconds()
        return 0.0

class MiningExecutor:
    def __init__(self, config: MiningConfig, monitor: ResourceMonitor):
        self.config = config
        self.monitor = monitor
        self.process: Optional[subprocess.Popen] = None

    def initialize(self) -> None:
        self.monitor.log_activity("Initializing mining components.")
        if not self.config.is_pool_enabled():
            self.monitor.log_activity("Mining disabled in configuration.")
            return
        if not self.config.get_pool_url():
            self.monitor.log_activity("No pool URL configured.")
            return

    def start_mining(self, miner_binary: str) -> bool:
        if not self.config.is_pool_enabled():
            self.monitor.log_activity("Cannot start mining: pool disabled.")
            return False

        try:
            # Validate binary path exists and is executable
            binary_path = Path(miner_binary).resolve()
            if not binary_path.exists():
                self.monitor.log_activity(f"Miner binary not found: {miner_binary}")
                return False
            if not os.access(binary_path, os.X_OK):
                self.monitor.log_activity(f"Miner binary not executable: {miner_binary}")
                return False

            # Construct command safely without shell=True
            # Using environment variables for sensitive data instead of hardcoding
            env = os.environ.copy()
            env["POOL_API_KEY"] = POOL_API_KEY
            env["WALLET_ADDRESS"] = WALLET_ADDRESS

            cmd = [str(binary_path), "-o", self.config.get_pool_url(), "-u", self.config.get_worker_name()]

            # Append nicehash flag if enabled
            if self.config.is_nicehash():
                cmd.append("-p", "x")

            self.monitor.log_activity(f"Starting miner: {' '.join(cmd)}")

            self.process = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                cwd=CONFIG_DIR,
                env=env,
                text=True
            )
            self.monitor.log_activity("Miner process started successfully.")
            return True

        except FileNotFoundError:
            self.monitor.log_activity(f"Miner binary not found: {miner_binary}")
            return False
        except PermissionError:
            self.monitor.log_activity(f"Permission denied to execute miner: {miner_binary}")
            return False
        except Exception as e:
            self.monitor.log_activity(f"Error starting miner: {e}")
            return False

    def run_maintenance(self) -> None:
        self.monitor.log_activity("Running maintenance checks.")
        if self.process and self.process.poll() is not None:
            self.monitor.log_activity("Miner process has exited unexpectedly.")
            self.process = None

    def stop_mining(self) -> None:
        if self.process:
            try:
                self.process.terminate()
                self.process.wait(timeout=10)
                self.monitor.log_activity("Miner process terminated gracefully.")
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.monitor.log_activity("Miner process killed forcefully.")
            except Exception as e:
                self.monitor.log_activity(f"Error stopping miner: {e}")
            finally:
                self.process = None

def ensure_directory_structure() -> None:
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        if not CONFIG_FILE.exists():
            config = MiningConfig(CONFIG_FILE)
            config._save_config()
            logging.info(f"Created default config at {CONFIG_FILE}")
    except OSError as e:
        print(f"Failed to create directory structure: {e}", file=sys.stderr)
        sys.exit(1)

def main() -> None:
    ensure_directory_structure()

    config = MiningConfig(CONFIG_FILE)
    monitor = ResourceMonitor(LOG_FILE)
    executor = MiningExecutor(config, monitor)

    try:
        executor.initialize()
        monitor.start()

        # Simulate mining execution with a placeholder binary path
        # In a real scenario, this would be the path to the actual miner executable
        miner_binary = "./miner_binary" 

        if executor.start_mining(miner_binary):
            # Simulate a running period
            import time
            time.sleep(5)
            executor.run_maintenance()
        else:
            monitor.log_activity("Mining failed to start.")

        executor.stop_mining()
        monitor.stop()

        print(f"Final Status: Mining session completed. Uptime: {monitor.get_uptime_seconds():.2f}s")

    except KeyboardInterrupt:
        monitor.log_activity("Interrupted by user.")
        executor.stop_mining()
        monitor.stop()
        print("Mining stopped by user.")
    except Exception as e:
        monitor.log_activity(f"Critical error: {e}")
        print(f"Critical error occurred: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
